using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using POS.API.Authorization;using POS.Application.CashShifts;using POS.Domain.Constants;
namespace POS.API.Controllers;
[ApiController,Route("api/cash-shifts"),Authorize,RequirePermission(PermissionKeys.SalesEdit)]public class CashShiftsController(CashShiftService service):ControllerBase{[HttpGet]public async Task<ActionResult<List<CashShiftDto>>>Get([FromQuery]Guid branchId,CancellationToken ct)=>Ok(await service.GetAsync(branchId,ct));[HttpPost]public async Task<ActionResult<CashShiftDto>>Open(OpenCashShiftRequest request,CancellationToken ct)=>Ok(await service.OpenAsync(request,ct));[HttpPost("{id:guid}/close")]public async Task<ActionResult<CashShiftDto>>Close(Guid id,CloseCashShiftRequest request,CancellationToken ct)=>Ok(await service.CloseAsync(id,request,ct));}
